/**
 * Every signal Orpheus displays, with its category:
 * - measured: read from the visitor's device with consent;
 * - simulated: generated by the simulation;
 * - inferred: estimated from measurements by a documented, validated model.
 *
 * No inferred signals exist. Microphone energy is the only measurement, and it is never presented as
 * breathing, heart rate, HRV, stress or any other physiological state.
 */
export type SignalCategory = 'measured' | 'simulated' | 'inferred';

export interface SignalDescriptor {
  id: string;
  label: string;
  category: SignalCategory;
  source: string;
  method: string;
  unit: string;
  indicates: string;
  doesNotIndicate: string;
  consentRequired: boolean;
}

