export const INFERRED_SIGNALS_NOTE =
  'No inferred signals: Orpheus implements no validated model that estimates anything about a person, so it displays none.';

export const signal = (id: string): SignalDescriptor => {
  const descriptor = SIGNALS.find((candidate) => candidate.id === id);
  if (!descriptor) throw new Error(`Unknown signal ${id}`);
  return descriptor;
};
